sys_script_include.script:
var TaskUtils = Class.create();
TaskUtils.prototype = {
    initialize: function() {
    },


    getTasksByEvent: function(eventId) {
        var tasks = [];
        var gr = new GlideRecord('Event_Task'); 
        gr.addQuery('u_event_id', eventId);
        gr.query();
        while (gr.next()) {
            tasks.push(gr.getDisplayValue('u_task_name')); 
        }
        return tasks;
    },



    isTaskOverdue: function(taskId) {
        var gr = new GlideRecord('Event_Task');
        if (gr.get(taskId)) {
            var dueDate = gr.getValue('u_due_date');
            var now = new GlideDateTime();
            return new GlideDateTime(dueDate) < now;
        }
        return false;
	},
    getTaskById: function(taskId) {
        var result = {};
        var gr = new GlideRecord('Event_Task');
        if (gr.get(taskId)) {
            result.task_name = gr.getValue('u_task_name');
            result.assigned_to = gr.getDisplayValue('assigned_to');
            result.due_date = gr.getDisplayValue('u_due_date');
            result.status = gr.getValue('u_status');
        }
        return result;
    },


    getTasksByDueDate: function(dueDate) {
        var tasks = [];
        var gr = new GlideRecord('Event_Task');
        gr.addQuery('u_due_date', dueDate);
        gr.query();
        while (gr.next()) {
            tasks.push(gr.getDisplayValue('u_task_name'));
        }
        return tasks;
    },



    type: 'TaskUtils'
};
